def run():
 DEST.mkdir(parents=True,exist_ok=True);(DEST/'data').mkdir(exist_ok=True)
 records=inventory();assert len({x['id'] for x in records})==len(records)
 for r in records:
  c=r['category'];name=r['name']
  img='ballet-dance' if c=='מחול' else 'gentle-fitness' if c=='התעמלות' else 'adult-crafts' if c=='אמנויות יצירה' else 'children-theatre' if c=='אמנויות הבמה' else 'live-music' if c=='מוזיקה ושירה' else 'digital-learning' if 'גיימינג' in name or 'לגו' in name or 'רובוט' in name else 'bread-baking' if 'אפייה' in name or 'שפים' in name else 'book-club' if c in ['למידה והעשרה','חשיבה והגיון'] else 'football' if 'כדורגל' in name else 'basketball' if 'כדורסל' in name else 'volleyball' if 'כדורעף' in name or 'מאמאנט' in name or 'נטבול' in name else 'fitness'
  if c=='אמנויות לחימה':img='martial-arts'
  if c=='חשיבה והגיון':img='chess'
  if 'מדע' in name:img='science'
  if 'כלבים' in name:img='dog-training'
  if 'אנגלית' in name:img='english'
  if 'טניס' in name:img='table-tennis' if 'שולחן' in name else 'tennis'
  if any(t in name for t in ['אופניים','רולר','סקייט']):img='cycling-skating'
  if c=='ספורט מים':img='pool'
  if c=='התעמלות' and '60+' not in r['ages']:img='fitness'
  if 'ציור' in name or ('אמנויות יצירה'==c and '60+' not in r['ages']):img='painting'
  if img in ['fitness','martial-arts','chess','science','dog-training','english','table-tennis','tennis','painting']:
   r['image_credit']='מאגר תמונות הפעילות של ISNET — להמחשה בלבד; אינה תמונה של החוג בקריית גת.'
  r['image']='assets/classes/'+img+'.jpg'
 payload={'city':'קריית גת','scope':'Verified published 2026–2027 programme; groups and programmes with unspecified timetable remain explicitly marked.','retrieved_on':'2026-10-29','records':records}
 (DEST/'data/classes.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
 featured=[]
 for name in ['מובמנט — מחול לגיל הרך','תיאטרון אורנה פורת','קונסרבטוריון — פסנתר','מדע ורפואה','בית הספר לכדורגל','יוגה']:
  r=next(x for x in records if x['name']==name);featured.append({'id':r['id'],'display_title':name,'position':len(featured)+1,'sponsored':False})
 (DEST/'data/featured.json').write_text(json.dumps({'items':featured},ensure_ascii=False,indent=2)+'\n')
 print('Reviewed Kiryat Gat courses:',len(records))
if __name__=='__main__':run()
